return s.length ? s : VIDE;

// Devis : le journal (lib-journaliser), une enveloppe par compte : des identifiants et des décisions, jamais un nom, un contact, un texte ni un montant.
const D = $('Constituer les dossiers').first().json, ENVS = D.envs, DOSSIERS = D.dossiers, REJETS = D.rejets;
const ENVB = {}; for (const e of ENVS) ENVB[e.organisation_id] = e;
